#include "resident/checkpoint/checkpoint_economic_index_copy.hpp"
// 索引先按真实任期与site/account授权；页面只走合法ID序列，不泄露其他组织的暂停数量。
#include "fiscal_taxpayer_continuity_view.hpp"
#include "fiscal_taxpayer_continuity_internal.hpp"
namespace hanmo::resident {
namespace {
bool same_identity(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
LocalEconomyAuthorityKey key(const ActingAuthority& a){return {a.organization_id,a.office_id,a.authority_epoch,a.actor_id};}
// 暂停整期只给原受益组织读；个别原纳税组织仍只可读自己欠款，不借此枚举其他税源。
bool allowed(const OrganizationRead& org,const FiscalPolicySnapshot& policy,const ActingAuthority& authority,const FiscalSourceAssessment* debt){
 if(!org.authorize(authority,"inspect_local_economy",{ScopeRef::Kind::site,policy.site_id},0).ok)return false;StableId account;
 if(authority.organization_id==policy.organization_id)account=policy.public_wallet_id;else if(debt&&debt->owner.kind==Owner::Kind::organization&&authority.organization_id==debt->owner.id)account=debt->wallet_id;else return false;
 return org.authorize(authority,"inspect_local_economy",{ScopeRef::Kind::account,account},0).ok;
}
Outcome<FiscalPolicySnapshot> policy(const FiscalTaxpayerContinuityViewContext& x,const FiscalTaxpayerSuspendedPeriod& pause){const auto* district=x.catalog.districts.find(pause.district_id);if(!district)return {false,{},common_failure("MissingFiscalDistrict",pause.district_id).error};auto selected=x.policies.fiscal_policy_for_assessment_source(district->site_id,pause.due_tick,pause.policy_source_fact_id);if(!selected.ok)return {false,{},selected.error};if(!selected.value)return {false,{},common_failure("FiscalTaxpayerSuspendedPolicyMissing",pause.period_id).error};return {true,*selected.value,{}};}
}
// 完整新账验证只在建索引时执行；该索引绑定当前World/玩家/地点，绝不写入冷段。
Outcome<FiscalSettlementIndex> build_fiscal_taxpayer_continuity_index(const FiscalTaxpayerContinuityViewContext& x){
 if(x.continuity.phase)return {false,{},common_failure("FiscalTaxpayerPageRequiresCommittedClock").error};auto valid=validate_fiscal_settlement(x.common,x.economy,x.local,x.organizations,x.policies,x.catalog,x.fiscal,&x.takeover,&x.continuity);if(!valid.ok)return {false,{},valid.error};
 auto index=build_fiscal_settlement_index(x.common,x.fiscal,x.organization,x.organizations);for(auto& row:index.sources)index_memory::clear_values(index.text_memory,row.second);
 for(const auto& row:x.fiscal.assessments.rows()){const auto& debt=row.second;if(debt.cash.paid_amount==debt.cash.original_due&&debt.grain.paid_amount==debt.grain.original_due)continue;const auto* period=x.fiscal.periods.find(debt.period_id);const auto* district=period?x.catalog.districts.find(period->district_id):nullptr;const auto* source=district?district->sources.find(debt.source_id):nullptr;if(!period||!period->policy||!source)return {false,{},common_failure("MissingFiscalSource",row.first).error};auto current=fiscal_taxpayer_continuity_detail::available(x.common,*source,debt.owner,x.continuity,x.common.tick());if(!current.ok)return {false,{},current.error};if(current.value||period->policy->site_id!=index.place_id)continue;for(const auto& authority:index.authorities)if(allowed(x.organizations,*period->policy,authority,&debt))index_memory::authority_entry(index.text_memory,index.sources,authority).push_back(index_memory::copy(index.text_memory,row.first));}
 for(const auto& row:x.continuity.state.suspended_periods.rows()){auto selected=policy(x,row.second);if(!selected.ok)return {false,{},selected.error};if(selected.value.site_id!=index.place_id)continue;for(const auto& authority:index.authorities)if(allowed(x.organizations,selected.value,authority,nullptr))index_memory::authority_entry(index.text_memory,index.sources,authority).push_back(index_memory::copy(index.text_memory,row.first));}
 return {true,std::move(index),{}};
}
// 旧游标、换人/换World、撤grant或已恢复收款都拒旧索引；查询不生成暂停、不推进周期。
Outcome<FiscalTaxpayerContinuityPage> query_fiscal_taxpayer_continuity(const FiscalTaxpayerContinuityViewContext& x,const FiscalSettlementIndex& index,const LocalEconomyQuery& query){
 auto fail=[](const StableId& code)->Outcome<FiscalTaxpayerContinuityPage>{return {false,{},common_failure(code).error};};const auto& common=x.common;
 if(x.continuity.phase||x.fiscal.last_step_tick!=common.tick()||x.continuity.state.last_step_tick!=common.tick())return fail("FiscalTaxpayerPageRequiresCommittedClock");if(query.observer_actor_id!=common.state().metadata.player_actor_id||query.observer_actor_id.empty())return fail("LocalEconomyObserverRequired");auto at=common.resolved_location(query.observer_actor_id);const auto* location=at.ok?std::get_if<SettlementLocation>(&at.value):nullptr;const auto* actor=common.actor(query.observer_actor_id);if(!actor||!actor->alive||!location||location->place_id!=query.place_id)return fail("LocalEconomyPlaceNotObservable");if(!same_identity(index.identity,common.state().identity)||index.observer_actor_id!=query.observer_actor_id||index.place_id!=query.place_id)return fail("StaleFiscalSettlementIndex");
 const CheckpointVector<StableId> empty;const auto* sources=&empty;if(query.authority){const auto& authority=*query.authority;if(authority.actor_id!=query.observer_actor_id)return fail("LocalEconomyAuthorityActorMismatch");auto authorized=x.organizations.authorize(authority,"inspect_local_economy",{ScopeRef::Kind::site,query.place_id},0);if(!authorized.ok)return {false,{},authorized.error};auto found=index.sources.find(key(authority));if(found==index.sources.end())return fail("StaleFiscalSettlementIndex");sources=&found->second;}
 Integer offset=0;if(query.cursor){const auto& cursor=*query.cursor;if(!same_identity(cursor.identity,common.state().identity)||cursor.observer_actor_id!=query.observer_actor_id||cursor.place_id!=query.place_id||cursor.authority.has_value()!=query.authority.has_value()||(cursor.authority&&key(*cursor.authority)!=key(*query.authority)))return fail("StaleLocalEconomyCursor");offset=cursor.offset;}if(sources->size()>static_cast<std::size_t>(INT64_MAX)||offset<0||offset>static_cast<Integer>(sources->size()))return fail("InvalidLocalEconomyCursor");
 FiscalTaxpayerContinuityPage out;auto& page=out.base;page.identity=common.state().identity;page.observer_actor_id=query.observer_actor_id;page.place_id=query.place_id;page.authorities.assign(index.authorities.begin(),index.authorities.end());page.cursor=offset;
 while(offset<static_cast<Integer>(sources->size())&&out.rows.size()<static_cast<std::size_t>(local_economy_page_limit)){
  const auto& id=(*sources)[static_cast<std::size_t>(offset++)];++page.scanned;if(!query.authority)return fail("StaleFiscalSettlementIndex");FiscalTaxpayerContinuityRow row;
  if(const auto* pause=x.continuity.state.suspended_periods.find(id)){auto selected=policy(x,*pause);if(!selected.ok)return {false,{},selected.error};if(selected.value.site_id!=query.place_id||!allowed(x.organizations,selected.value,*query.authority,nullptr))return fail("StaleFiscalSettlementIndex");row={"fiscal_taxpayer_period_suspended",id,{},pause->district_id,selected.value.site_id,selected.value.organization_id,pause->policy_source_fact_id,pause->due_tick,0,0,pause->blocked_source_ids};}
  else{const auto* debt=x.fiscal.assessments.find(id);const auto* period=debt?x.fiscal.periods.find(debt->period_id):nullptr;const auto* district=period?x.catalog.districts.find(period->district_id):nullptr;const auto* source=debt&&district?district->sources.find(debt->source_id):nullptr;if(!debt||!period||!period->policy||!source||period->policy->site_id!=query.place_id||!allowed(x.organizations,*period->policy,*query.authority,debt))return fail("StaleFiscalSettlementIndex");auto owned=fiscal_taxpayer_continuity_detail::available(common,*source,debt->owner,x.continuity,common.tick());if(!owned.ok)return {false,{},owned.error};if(owned.value)return fail("StaleFiscalSettlementIndex");row={"fiscal_taxpayer_collection_paused",period->id,debt->id,period->district_id,period->policy->site_id,period->policy->organization_id,period->policy->source_fact_id,period->due_tick,debt->cash.original_due-debt->cash.paid_amount,debt->grain.original_due-debt->grain.paid_amount,{debt->source_id}};}
  out.rows.push_back(std::move(row));
 }
 if(offset<static_cast<Integer>(sources->size()))page.next_cursor=LocalEconomyCursor{page.identity,query.observer_actor_id,query.place_id,query.authority,offset};return {true,std::move(out),{}};
}
// 只编码有限DTO，旧财政页保持其原字段；不把可花余额、未授权原账或全文政策载入UI。
BoundaryValue encode_fiscal_taxpayer_continuity_page(const FiscalTaxpayerContinuityPage& page){using V=BoundaryValue;auto out=encode_fiscal_settlement_page(page.base);V::Array rows;for(const auto& row:page.rows)rows.push_back(boundary::obj({{"kind",V{row.kind}},{"period_id",V{row.period_id}},{"assessment_id",V{row.assessment_id}},{"district_id",V{row.district_id}},{"site_id",V{row.site_id}},{"organization_id",V{row.organization_id}},{"policy_fact_id",V{row.policy_fact_id}},{"due_tick",V{row.due_tick}},{"cash_outstanding",V{row.cash_outstanding}},{"grain_outstanding",V{row.grain_outstanding}},{"source_ids",boundary::string_array(row.source_ids)},{"reason",V{"original_taxpayer_assets_captured"}}}));out.find("rows")->data=std::move(rows);return out;}
}
